import { db } from '../db';
import { Invoice } from '../types';

// Returns all unpaid invoices for the given userId
export async function getUnpaidInvoices(userId: string): Promise<Invoice[]> {
  return db.invoice.findMany({
    where: { userId, status: 'unpaid' },
    orderBy: { dueDate: 'asc' },
  });
}

// Charges the default card of userId; throws if none
export async function chargeDefaultCard(userId: string, amountCents: number) {
  const card = await db.card.findFirst({ where: { userId, isDefault: true } });
  if (!card) {
    throw new Error(`No default card for user ${userId}`);
  }
  return db.charge.create({
    data: { userId, cardId: card.id, amountCents },
  });
}

export function invoiceKey(userId: string, invoiceId: string) {
  return `${userId}:${invoiceId}`;
}
